mapper.select:
SELECT id, tenant_id, product_key, device_name, device_key, device_type, secret, status, connect_status, last_connected_at, last_disconnected_at, protocol_type, protocol_version, created_at, updated_at
FROM iot_device
WHERE product_key = #{productKey}
  AND device_key = #{deviceKey}

SELECT COUNT(1)
FROM iot_device
WHERE product_key = #{productKey}

mapper.update:
UPDATE iot_device
SET device_type = CASE
        WHEN #{deviceType} IS NULL OR #{deviceType} = '' THEN device_type
        ELSE #{deviceType}
    END,
    protocol_type = CASE
        WHEN #{protocolType} IS NULL OR #{protocolType} = '' THEN protocol_type
        ELSE #{protocolType}
    END,
    protocol_version = CASE
        WHEN #{protocolVersion} IS NULL OR #{protocolVersion} = '' THEN protocol_version
        ELSE #{protocolVersion}
    END,
    updated_at = CURRENT_TIMESTAMP
WHERE product_key = #{productKey}
  AND device_key = #{deviceKey}

UPDATE iot_device
SET device_name = #{deviceName},
    updated_at = CURRENT_TIMESTAMP
WHERE product_key = #{productKey}
  AND device_key = #{deviceKey}

UPDATE iot_device
SET status = #{status},
    updated_at = CURRENT_TIMESTAMP
WHERE product_key = #{productKey}
  AND device_key = #{deviceKey}

UPDATE iot_device
SET connect_status = #{connectStatus},
    updated_at = CURRENT_TIMESTAMP
WHERE product_key = #{productKey}
  AND device_key = #{deviceKey}

UPDATE iot_device
SET secret = #{secret},
    updated_at = CURRENT_TIMESTAMP
WHERE product_key = #{productKey}
  AND device_key = #{deviceKey}

mapper.delete:
DELETE FROM iot_device
WHERE product_key = #{productKey}
  AND device_key = #{deviceKey}
